<?php declare(strict_types=1);require_once __DIR__.'/../../../bootstrap/app.php';use App\Services\Auth;use App\Services\OfferService;use App\Support\Url;Auth::requirePermission('OFFER_VIEW_OWN');$rows=OfferService::ownQueue();$pageTitle='My Transport Offers';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>My transport offers</h1><p>Respond to McCollins offers for your eligible fleet.</p></div><span class="badge"><?=h(count($rows))?> records</span></div><div class="card table-wrap"><table><thead><tr><th>Offer</th><th>Load</th><th>Truck</th><th>TZS</th><th>USD</th><th>Status</th><th>Expires UTC</th><th></th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['offer_thread_ref'].' · v'.$r['version_no'])?></td><td><?=h($r['load_ref'])?></td><td><?=h($r['registration_number'])?></td><td><?=h(number_format((float)$r['offered_amount_tzs'],2))?></td><td><?=h(number_format((float)$r['offered_amount_usd'],2))?></td><td><span class="status-pill status-<?=h($r['offer_status'])?>"><?=h(str_replace('_',' ',$r['offer_status']))?></span></td><td><?=h($r['expires_at'])?></td><td><a href="<?=h(Url::to('carrier/offers/view.php?id='.$r['offer_id']))?>">Open</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="8" class="muted">No transport offers.</td></tr><?php endif;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
